sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var Constants = x_gegis_ins_policy.Constants;
    var APPLIED = Constants.CHOICE.DISPOSITION.APPLIED;

    var isNewlyApplied = current.operation() == 'insert' && String(current.getValue('disposition')) == APPLIED;
    var justConfirmed = current.operation() == 'update' && previous &&
        String(previous.getValue('disposition')) != APPLIED && String(current.getValue('disposition')) == APPLIED;
    if (!isNewlyApplied && !justConfirmed)
        return;

    // LOA allow-list: TIV, LOB, and the closest proxies this schema actually has
    // for "CAT exposure" (exposure_item.flood / .earthquake booleans) and
    // "territory" (location.state) - x_gegis_ins_policy_exposure_item and
    // x_gegis_ins_policy_location have no dedicated cat_exposure/territory
    // columns. ASSUMPTION, documented once here: all of these except
    // total_insured_value are bucketed under property_count_change by
    // UWTriggerReasonResolver until the catalog grows dedicated codes.
    var LOA_ALLOW_LIST = ['total_insured_value', 'line_of_business', 'state', 'flood', 'earthquake'];

    var submissionId = String(current.getValue('submission'));
    if (!submissionId) {
        gs.error('[LOA trigger on extraction confirmed] extraction ' + current.getUniqueValue() +
            ' has no submission - cannot resolve its submission_line(s), skipped');
        return;
    }

    var submissionGr = new GlideRecord('x_gegis_ins_policy_submission');
    var submissionType = submissionGr.get(submissionId) ? String(submissionGr.getValue('submission_type')) : '';

    var newSnapshot = _buildSnapshot(current.getUniqueValue(), LOA_ALLOW_LIST);
    var priorExtractionId = String(current.getValue('supersedes'));
    var oldSnapshot = priorExtractionId ? _buildSnapshot(priorExtractionId, LOA_ALLOW_LIST) : {};

    var changedFields = new UWFieldSnapshotDiff().diff(oldSnapshot, newSnapshot, LOA_ALLOW_LIST);

    // isFirstEver is deliberately NEVER derived from extraction.supersedes for
    // LOA: LOA's "first ever" anchor is the underwriter's first assignment (see
    // "LOA trigger on first underwriter assignment"), not the first extraction.
    // A first-ever extraction that carries no TIV/renewal/endorsement/property
    // signal simply raises no LOA version here.
    var triggerReasonId = new UWTriggerReasonResolver().resolve({
        consumer: 'loa',
        changedFields: changedFields,
        isRenewal: submissionType == Constants.CHOICE.SUBMISSION_TYPE.RENEWAL,
        isEndorsement: submissionType == Constants.CHOICE.SUBMISSION_TYPE.ENDORSEMENT
    });
    if (!triggerReasonId)
        return; // resolver already gs.error'd with full context, or nothing LOA-relevant changed

    var versionService = new LOAEvaluationVersionService();
    var lines = new GlideRecord('x_gegis_ins_policy_submission_line');
    lines.addQuery('submission', submissionId);
    lines.query();
    var created = 0;
    while (lines.next()) {
        if (versionService.createNextVersion(lines.getUniqueValue(), triggerReasonId))
            created++;
    }
    if (!created)
        gs.error('[LOA trigger on extraction confirmed] no submission_line rows found for submission ' +
            submissionId + ' - no loa_evaluation created for extraction ' + current.getUniqueValue());

    function _buildSnapshot(extractionId, allowList) {
        var snapshot = {};
        var field = new GlideRecord('x_gegis_ins_policy_extraction_field');
        field.addQuery('extraction', extractionId);
        field.addQuery('target_column', 'IN', allowList.join(','));
        field.query();
        while (field.next())
            snapshot[String(field.getValue('target_column'))] = String(field.getValue('final_value'));
        return snapshot;
    }

})(current, previous);
